import type { SharedData } from './global_visitor_context';
import { GlobalVisitorContext } from './global_visitor_context';
import { QueryVisitorContext } from './contexts';
import type {
  CommandVisitorContext,
  HeaderCommandVisitorContext,
  VisitorContext,
} from './contexts';
import type {
  AstNodeToVisitorName,
  EnsureFunction,
  ESQLAstExpressionNode,
  UndefinedToVoid,
  VisitorMethods,
} from './types';
import type { ESQLAstQueryExpression, ESQLCommand, ESQLProperNode } from '@elastic/esql-types';
import { Builder } from '@elastic/esql-ast';

export interface VisitorOptions<
  Methods extends VisitorMethods = VisitorMethods,
  Data extends SharedData = SharedData,
> {
  visitors?: Methods;
  data?: Data;
}

export class Visitor<
  Methods extends VisitorMethods = VisitorMethods,
  Data extends SharedData = SharedData,
> {
  /**
   * Finds the most specific node immediately after the given position. If the
   * position is inside a node, it will return the node itself. If no node is
   * found, it returns `null`.
   *
   * @param ast ES|QL AST
   * @param pos Offset position in the source text
   * @returns The node at or after the given position
   */
  public static readonly findNodeAtOrAfter = (
    ast: ESQLAstQueryExpression,
    pos: number
  ): ESQLProperNode | null => {
    const visitCommand = (
      ctx: CommandVisitorContext | HeaderCommandVisitorContext
    ): ESQLProperNode | null => {
      for (const child of ctx.arguments()) {
        const { location: childLocation } = child;
        if (!childLocation) continue;
        const isInsideChild = childLocation.min <= pos && childLocation.max >= pos;
        if (isInsideChild) return ctx.visitExpression(child, undefined);
        const isBeforeChild = childLocation.min > pos;
        if (isBeforeChild) {
          return ctx.visitExpression(child, undefined) || child;
        }
      }
      return null;
    };

    return new Visitor()
      .on('visitExpression', (ctx): ESQLProperNode | null => {
        const node = ctx.node;
        const location = node.location;
        if (!location) return null;
        const isBefore = location.min > pos;
        let isFirstChild = true;
        for (const child of ctx.arguments()) {
          const { location: childLocation } = child;
          if (!childLocation) continue;
          if (isFirstChild) {
            isFirstChild = false;
            if (isBefore) {
              const isChildAtOffset =
                ctx.node.location && ctx.node.location.min < childLocation.min;
              if (isChildAtOffset) return node;
              return ctx.visitExpression(child, undefined) || child;
            }
          }
          const isInsideChild = childLocation.min <= pos && childLocation.max >= pos;
          if (isInsideChild) return ctx.visitExpression(child, undefined);
          const isBeforeChild = childLocation.min > pos;
          if (isBeforeChild) {
            return ctx.visitExpression(child, undefined) || child;
          }
        }
        return null;
      })
      .on('visitParensExpression', (ctx): ESQLProperNode | null => {
        const parens = ctx.node;
        const parensLocation = parens.location;

        if (!parensLocation) {
          return null;
        }

        // Handle position before opening "("
        if (parensLocation.min > pos) {
          return parens;
        }

        return null;
      })
      .on('visitCommand', visitCommand)
      .on('visitHeaderCommand', visitCommand)
      .on('visitQuery', (ctx): ESQLProperNode | null => {
        for (const node of ctx.headerCommands()) {
          const { location } = node;
          if (!location) continue;
          const isInside = location.min <= pos && location.max >= pos;
          if (isInside) return ctx.visitHeaderCommand(node, undefined);
          const isBefore = location.min > pos;
          if (isBefore) return node;
        }

        for (const node of ctx.commands()) {
          const { location } = node;
          if (!location) continue;
          const isInside = location.min <= pos && location.max >= pos;
          if (isInside) return ctx.visitCommand(node);
          const isBefore = location.min > pos;
          if (isBefore) return node;
        }

        return null;
      })
      .visitQuery(ast);
  };

  /**
   * Finds the most specific node immediately before the given position. If the
   * position is inside a node, it will return the node itself. If no node is
   * found, it returns `null`.
   *
   * @param ast ES|QL AST
   * @param pos Offset position in the source text
   * @returns The node at or before the given position
   */
  public static readonly findNodeAtOrBefore = (
    ast: ESQLAstQueryExpression,
    pos: number
  ): ESQLProperNode | null => {
    const visitCommand = (
      ctx: CommandVisitorContext | HeaderCommandVisitorContext
    ): ESQLProperNode | null => {
      const nodes = [...ctx.arguments()];
      for (let i = nodes.length - 1; i >= 0; i--) {
        const node = nodes[i];
        if (!node) continue;
        const { location } = node;
        if (!location) continue;
        const isInside = location.min <= pos && location.max >= pos;
        if (isInside) return ctx.visitExpression(node, undefined);
        const isAfter = location.max < pos;
        if (isAfter) {
          if (ctx.node.location && ctx.node.location.max >= location.max) {
            return ctx.visitExpression(node, undefined) || node;
          }
          return node;
        }
      }
      return null;
    };

    return new Visitor()
      .on('visitExpression', (ctx): ESQLProperNode | null => {
        const nodeLocation = ctx.node.location;
        const nodes = [...ctx.arguments()];

        if (nodeLocation && nodeLocation.max < pos) {
          const last = nodes[nodes.length - 1];
          if (last && last.location && last.location.max === nodeLocation.max) {
            return ctx.visitExpression(last, undefined) || last;
          } else {
            return ctx.node;
          }
        }

        for (let i = nodes.length - 1; i >= 0; i--) {
          const node = nodes[i];
          if (!node) continue;
          const { location } = node;
          if (!location) continue;
          const isInside = location.min <= pos && location.max >= pos;
          if (isInside) return ctx.visitExpression(node, undefined);
          const isAfter = location.max < pos;
          if (isAfter) {
            return ctx.visitExpression(node, undefined) || node;
          }
        }

        return null;
      })
      .on('visitParensExpression', (ctx): ESQLProperNode | null => {
        const parens = ctx.node;
        const parensLocation = parens.location;

        if (!parensLocation) {
          return null;
        }

        const childQuery = ctx.child();

        // Handle comments between end of subquery content and closing ")"
        if (childQuery?.type === 'query' && childQuery.location) {
          if (childQuery.location.max < pos && pos <= parensLocation.max) {
            return parens;
          }
        }

        // Handle comments immediately after closing ")"
        if (pos > parensLocation.max) {
          return parens;
        }

        // For comments inside parens but before/during content, continue visiting children
        return null;
      })
      .on('visitCommand', visitCommand)
      .on('visitHeaderCommand', visitCommand)
      .on('visitQuery', (ctx): ESQLProperNode | null => {
        const nodes = [...ctx.headerCommands(), ...ctx.commands()];
        for (let i = nodes.length - 1; i >= 0; i--) {
          const node = nodes[i];
          if (!node) continue;
          const { location } = node;
          if (!location) continue;
          const isInside = location.min <= pos && location.max >= pos;
          if (isInside) {
            if (node.type === 'command') return ctx.visitCommand(node);
            else if (node.type === 'header-command') {
              return ctx.visitHeaderCommand(node, undefined);
            } else return node;
          }
          const isAfter = location.max < pos;
          if (isAfter) {
            if (node.type === 'command') return ctx.visitCommand(node) || node;
            return node;
          }
        }

        return null;
      })
      .visitQuery(ast);
  };

  public readonly ctx: GlobalVisitorContext<Methods, Data>;

  constructor(protected readonly options: VisitorOptions<Methods, Data> = {}) {
    this.ctx = new GlobalVisitorContext<Methods, Data>(
      options.visitors ?? ({} as Methods),
      options.data ?? ({} as Data)
    );
  }

  public visitors<NewMethods extends VisitorMethods<Methods, Data>>(
    visitors: NewMethods
  ): Visitor<Methods & NewMethods, Data> {
    Object.assign(this.ctx.methods, visitors);
    return this as unknown as Visitor<Methods & NewMethods, Data>;
  }

  public on<
    K extends keyof VisitorMethods<Methods, Data>,
    F extends VisitorMethods<Methods, Data>[K],
  >(visitor: K, fn: F): Visitor<Methods & { [KK in K]: F }, Data> {
    Object.assign(this.ctx.methods, { [visitor]: fn });
    return this as unknown as Visitor<Methods & { [KK in K]: F }, Data>;
  }

  /**
   * Traverse any AST node given any visitor context.
   *
   * @param node AST node to traverse.
   * @param ctx Traversal context.
   * @returns Result of the visitor callback.
   */
  public visit<Ctx extends VisitorContext<Methods, Data>>(
    ctx: Ctx,
    input: UndefinedToVoid<Parameters<NonNullable<Methods[AstNodeToVisitorName<Ctx['node']>]>>[1]>
  ): ReturnType<EnsureFunction<Methods[AstNodeToVisitorName<Ctx['node']>]>> {
    const node = ctx.node;
    if (node instanceof Array) {
      throw new Error(`Unsupported node type: ${typeof node}`);
    } else if (node && typeof node === 'object') {
      switch (node.type) {
        case 'query': {
          this.ctx.assertMethodExists('visitQuery');
          return this.ctx.methods.visitQuery!(
            ctx as unknown as QueryVisitorContext<Methods, Data>,
            input
          ) as ReturnType<NonNullable<Methods['visitQuery']>>;
        }
        case 'header-command': {
          this.ctx.assertMethodExists('visitHeaderCommand');
          return this.ctx.methods.visitHeaderCommand!(
            ctx as unknown as HeaderCommandVisitorContext<Methods, Data>,
            input
          ) as ReturnType<NonNullable<Methods['visitHeaderCommand']>>;
        }
        case 'command': {
          this.ctx.assertMethodExists('visitCommand');
          return this.ctx.methods.visitCommand!(
            ctx as unknown as CommandVisitorContext<Methods, Data>,
            input
          ) as ReturnType<NonNullable<Methods['visitCommand']>>;
        }
      }
    }
    throw new Error(`Unsupported node type: ${typeof node}`);
  }

  /**
   * Traverse the root node of ES|QL query with default context.
   *
   * @param node Query node to traverse.
   * @param input Input to pass to the first visitor.
   * @returns The result of the query visitor.
   */
  public visitQuery(
    nodeOrCommands: ESQLAstQueryExpression | ESQLAstQueryExpression['commands'],
    input: UndefinedToVoid<Parameters<NonNullable<Methods['visitQuery']>>[1]>
  ) {
    const node = Array.isArray(nodeOrCommands)
      ? Builder.expression.query(nodeOrCommands)
      : nodeOrCommands;
    const queryContext = new QueryVisitorContext(this.ctx, node, null);

    return this.visit(queryContext, input);
  }

  /**
   * Traverse starting from known command node with default context.
   *
   * @param node Command node to traverse.
   * @param input Input to pass to the first visitor.
   * @returns The output of the visitor.
   */
  public visitCommand(
    node: ESQLCommand,
    input: UndefinedToVoid<Parameters<NonNullable<Methods['visitCommand']>>[1]>
  ) {
    this.ctx.assertMethodExists('visitCommand');
    return this.ctx.visitCommand(null, node, input);
  }

  /**
   * Traverse starting from known header command node with default context.
   *
   * @param node Header command node to traverse.
   * @param input Input to pass to the first visitor.
   * @returns The output of the visitor.
   */
  public visitHeaderCommand(
    node: import('@elastic/esql-types').ESQLAstHeaderCommand,
    input: UndefinedToVoid<Parameters<NonNullable<Methods['visitHeaderCommand']>>[1]>
  ) {
    this.ctx.assertMethodExists('visitHeaderCommand');
    return this.ctx.visitHeaderCommand(null, node, input);
  }

  /**
   * Traverse starting from known expression node with default context.
   *
   * @param node Expression node to traverse.
   * @param input Input to pass to the first visitor.
   * @returns The output of the visitor.
   */
  public visitExpression(
    node: ESQLAstExpressionNode,
    input: UndefinedToVoid<Parameters<NonNullable<Methods['visitExpression']>>[1]>
  ) {
    this.ctx.assertMethodExists('visitExpression');
    return this.ctx.visitExpression(null, node, input);
  }
}
